I'll change it to:

```python
class APIKeyBase(SecurityBase):
    def format_www_authenticate_header_value(self) -> str:
        return f'ApiKey in="{self.model.in_}", name="{self.model.name}"'

    def check_api_key(
        self,
        api_key: Optional[str],
        auto_error: bool,
        not_authenticated_status_code: Optional[int] = None,
    ) -> Optional[str]:
        if not api_key:
            if auto_error:
                status_code = not_authenticated_status_code or HTTP_401_UNAUTHORIZED
                headers = {}
                if not not_authenticated_status_code:
                    headers["WWW-Authenticate"] = self.format_www_authenticate_header_value()
                raise HTTPException(
                    status_code=status_code, detail="Not authenticated", headers=headers
                )
            return None
        return api_key
```

